import {
    Component,
    EventEmitter,
    OnInit,
    Output,
    inject,
    signal,
    viewChild,
} from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import {
    PlaceSystem,
    PlaceTrigger,
    TriggerActions,
    TriggerFunction,
    TriggerMailer,
    updateTrigger,
} from '@placeos/ts-client';

import { COMMA, ENTER, SPACE } from '@angular/cdk/keycodes';
import { FormsModule } from '@angular/forms';
import { form, FormField, submit } from '@angular/forms/signals';
import { MatChipGrid, MatChipsModule } from '@angular/material/chips';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { AsyncHandler } from '../../common/async-handler.class';
import { i18n } from '../../common/locale.service';
import { notifyError, notifySuccess } from '../../common/notifications';
import { DialogEvent, Identity } from '../../common/types';
import {
    applyTriggerActionFormSchema,
    generateTriggerActionFormModel,
} from '../../triggers/triggers.utilities';
import { ExecuteMethodFieldComponent } from '../custom-fields/system-exec/execute-method-field.component';
import { FullscreenModalShellComponent } from '../fullscreen-modal-shell.component';
import { IconComponent } from '../icon.component';
import { TranslatePipe } from '../translate.pipe';

export interface TriggerActionModalData {
    /** Item to add/update the trigger on */
    system: PlaceSystem;
    /** Trigger to add/update */
    trigger: PlaceTrigger;
    /** Trigger Condition to edit */
    action?: TriggerMailer | TriggerFunction;
}

@Component({
    selector: 'trigger-action-modal',
    template: `
        <fullscreen-modal-shell
            [heading]="
                (is_new ? 'TRIGGERS.ACTION_NEW' : 'TRIGGERS.ACTION_EDIT')
                    | translate
            "
            [loading]="loading()"
            (save)="save()"
        >
            @if (form) {
                <form
                    trigger-action
                    class="flex w-full max-w-[calc(100vw-2rem)] flex-col"
                >
                    @if (form.action_type) {
                        <div class="field">
                            <label for="type">
                                {{ 'TRIGGERS.ACTION_FIELD_TYPE' | translate }}:
                            </label>
                            <mat-form-field appearance="outline">
                                <mat-select
                                    [formField]="form.action_type"
                                >
                                    @for (type of action_types; track type) {
                                        <mat-option [value]="type.id">
                                            {{ type.name }}
                                        </mat-option>
                                    }
                                </mat-select>
                            </mat-form-field>
                        </div>
                    }
                    @switch (formModel().action_type) {
                        @case ('emails') {
                            @if (form.emails) {
                                <div class="field">
                                    <label
                                        for="description"
                                        [class.error]="
                                            form.emails().touched() &&
                                            form.emails().invalid()
                                        "
                                    >
                                        {{
                                            'TRIGGERS.ACTION_EMAIL_ADDRESS'
                                                | translate
                                        }}
                                        <span>*</span>
                                    </label>
                                    <mat-form-field
                                        appearance="outline"
                                        class="w-full"
                                    >
                                        <mat-chip-grid
                                            #chipList
                                            [aria-label]="
                                                'TRIGGERS.ACTION_EMAIL_ADDRESS'
                                                    | translate
                                            "
                                        >
                                            @for (
                                                item of email_list;
                                                track item
                                            ) {
                                                <mat-chip-row
                                                    (removed)="
                                                        removeEmail(item)
                                                    "
                                                >
                                                    <div
                                                        class="max-w-md truncate"
                                                    >
                                                        {{ item }}
                                                    </div>
                                                    <button
                                                        matChipRemove
                                                        [attr.aria-label]="
                                                            'COMMON.REMOVE_ITEM'
                                                                | translate
                                                                    : {
                                                                          item: item,
                                                                      }
                                                        "
                                                    >
                                                        <icon>cancel</icon>
                                                    </button>
                                                </mat-chip-row>
                                            }
                                        </mat-chip-grid>
                                        <input
                                            [(ngModel)]="new_email"
                                            [ngModelOptions]="{
                                                standalone: true,
                                            }"
                                            [placeholder]="
                                                'TRIGGERS.ACTION_EMAIL_ADDRESS_LIST'
                                                    | translate
                                            "
                                            [matChipInputFor]="chipList"
                                            [matChipInputSeparatorKeyCodes]="
                                                separators
                                            "
                                            [matChipInputAddOnBlur]="true"
                                            (matChipInputTokenEnd)="
                                                addEmail($event.value);
                                                new_email = ''
                                            "
                                        />
                                    </mat-form-field>
                                </div>
                            }
                            @if (form.content) {
                                <div class="field">
                                    <label for="content">{{
                                        'TRIGGERS.ACTION_EMAIL_BODY' | translate
                                    }}</label>
                                    <mat-form-field appearance="outline">
                                        <textarea
                                            matInput
                                            placeholder="Email body contents..."
                                            [formField]="form.content"
                                        ></textarea>
                                    </mat-form-field>
                                </div>
                            }
                        }
                        @default {
                            @if (form.method_call) {
                                <div class="field">
                                    <label for="content">
                                        {{
                                            'TRIGGERS.ACTION_EXECUTE_SELECT'
                                                | translate
                                        }}
                                    </label>
                                    <execute-method-field
                                        [formField]="form.method_call"
                                        [system]="system"
                                        [can_execute]="false"
                                    ></execute-method-field>
                                </div>
                            }
                        }
                    }
                </form>
            }
        </fullscreen-modal-shell>
    `,
    styles: [``],
    imports: [
        FormsModule,
        MatFormFieldModule,
        FormField,
        MatInputModule,
        MatChipsModule,
        FullscreenModalShellComponent,
        ExecuteMethodFieldComponent,
        TranslatePipe,
        IconComponent,
        MatSelectModule,
    ],
})
export class TriggerActionModalComponent
    extends AsyncHandler
    implements OnInit
{
    private _dialog =
        inject<MatDialogRef<TriggerActionModalComponent>>(MatDialogRef);
    private _data = inject<TriggerActionModalData>(MAT_DIALOG_DATA);

    /** Emitter for events on the modal */
    @Output() public event = new EventEmitter<DialogEvent>();
    /** Whether actions are loading */
    public readonly loading = signal('');
    /** Form fields for trigger action */
    public readonly formModel = signal(
        generateTriggerActionFormModel(this._data.action),
    );
    public readonly form = form(this.formModel, applyTriggerActionFormSchema);
    /** Store for changes to actions */
    public actions: TriggerActions;
    /** List of seperators for storing emails */
    public readonly separators: number[] = [ENTER, COMMA, SPACE];
    /** Variable to hold new email addresses */
    public new_email = '';

    private readonly chip_list = viewChild<MatChipGrid>('chipList');

    /** List of available trigger action types */
    public action_types: Identity[] = [];

    /** Whether the triggers is new or not */
    public get is_new(): boolean {
        return !!this._data.action;
    }

    /** Template system to use for status variable bindings */
    public get system(): PlaceSystem {
        return this._data.system;
    }

    /** Template system to use for status variable bindings */
    public get trigger(): PlaceTrigger {
        return this._data.trigger;
    }

    public get email_list(): string[] {
        return (
            (this.formModel().emails ? this.formModel().emails : null) || []
        );
    }

    public ngOnInit() {
        this.action_types = [
            { id: 'function', name: i18n('TRIGGERS.ACTION_EXECUTE') },
            { id: 'emails', name: i18n('TRIGGERS.ACTION_EMAIL') },
        ];
    }

    /**
     * Add the given emails to the list
     * @param email New email
     */
    public addEmail(email: string): void {
        if (!email) {
            return;
        }
        const email_list = this.email_list;
        if (email_list.indexOf(email) < 0) {
            email_list.push(email);
        }
        this.formModel.update((model) => ({ ...model, emails: email_list }));
        this.chip_list().errorState = this.form.emails().invalid();
    }

    /**
     * Remove given email from the list
     * @param email Exisiting email
     */
    public removeEmail(email: string): void {
        const email_list = this.email_list;
        const index = email_list.indexOf(email);
        if (index >= 0) {
            email_list.splice(index, 1);
        }
        this.formModel.update((model) => ({ ...model, emails: email_list }));
        this.chip_list().errorState = this.form.emails().invalid();
    }

    public async save() {
        await submit(this.form, async () => undefined);
        if (this.form().invalid()) {
            return;
        }
        this.loading.set('Save trigger action...');
        if (this.formModel().action_type === 'emails') {
            this.updateMailers();
        } else {
            this.updateFunctions();
        }
        await updateTrigger(this.trigger.id, {
            ...this.trigger,
            actions: this.actions,
        }).then(
            (item) => {
                this.event.emit({
                    reason: 'done',
                    metadata: { trigger: item },
                });
                notifySuccess(
                    `Successfully ${
                        this.is_new ? 'added' : 'updated'
                    } condition to trigger`,
                );
                this._dialog.close();
            },
            (err) => {
                this.loading.set('');
                notifyError(
                    `Error ${
                        this.is_new ? 'adding' : 'updating'
                    } condition to trigger. Error: ${JSON.stringify(
                        err.response || err.message || err,
                    )}`,
                );
            },
        );
    }

    private updateMailers() {
        const mailers = this.trigger.actions.mailers;
        const new_mailer = {
            emails: this.formModel().emails,
            content: this.formModel().content,
        };
        if (this._data.action) {
            const old_mailer = JSON.stringify(this._data.action || {});
            const index = mailers.findIndex(
                (a_mailer) => JSON.stringify(a_mailer) === old_mailer,
            );
            mailers.splice(index, 1, new_mailer);
        } else {
            mailers.push(new_mailer);
        }
        this.actions = { ...this.trigger.actions, mailers };
    }

    private updateFunctions() {
        const functions = this.trigger.actions.functions;
        if (this._data.action) {
            const old_function = JSON.stringify(this._data.action);
            const index = functions.findIndex(
                (fn) => JSON.stringify(fn) === old_function,
            );
            functions.splice(index, 1, this.formModel().method_call);
        } else {
            functions.push(this.formModel().method_call);
        }
        this.actions = { ...this.trigger.actions, functions };
    }
}
